def chk3(items, w=128):
    return table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in items], [f"{w}mm", "18mm", "18mm", "18mm"])


def tall(html, h):
    return html.replace("<td></td>", f'<td style="height:{h}mm"></td>')


def compact(html):
    return html.replace('class="t"', 'class="t compact"')


def card(t, lh=2):
    return f'<div class="card" style="line-height:{lh}">{t}</div>'


def texte(titre, paras, src="texte écrit pour le cahier", fs=9.4):
    p = "".join(f'<p style="margin:1.1mm 0"><b class="xs" style="color:{MC}">§{i}</b> {t}</p>' for i, t in enumerate(paras, 1))
    return f'<div class="card" style="background:#fff;font-size:{fs}pt;line-height:1.44;padding:2.5mm 4mm"><b style="color:{MC}">{titre}</b> <span class="xs muted">({src})</span>{p}</div>'


def parcours():
    """Frise de l'année en DASPA (à compléter)."""
    st = [("🚪", "Mon arrivée"), ("🗣️", "Mes premiers mots"), ("📚", "Ma première leçon réussie"), ("🤝", "Un(e) ami(e)"), ("🏆", "Ma plus grande fierté"), ("🎓", "Ma passerelle")]
    out = ""
    for i, (ic, t) in enumerate(st):
        out += (f'<div style="flex:1;text-align:center"><div style="font-size:16pt">{ic}</div><div style="width:9mm;height:9mm;border-radius:50%;background:{MC};color:#fff;font-weight:800;margin:0 auto;display:flex;align-items:center;justify-content:center">{i + 1}</div>'
                f'<div class="xs" style="margin-top:1mm;font-weight:700">{t}</div><div class="line" style="margin:3mm 1mm 0"></div><div class="line" style="margin:3mm 1mm 0"></div></div>')
    return f'<div style="position:relative"><div style="position:absolute;top:13mm;left:6%;right:6%;height:2px;background:{MC}"></div><div style="display:flex;gap:1mm;position:relative">{out}</div></div>'


def radar(labs, w=64):
    """Radar vide (0-4) pour un bilan de compétences."""
    n = len(labs)
    cx, cy, R = 60, 52, 32
    pts = lambda r: [(cx + r * math.sin(2 * math.pi * k / n), cy - r * math.cos(2 * math.pi * k / n)) for k in range(n)]
    g = ""
    for lv in range(1, 5):
        g += '<polygon points="' + " ".join(f"{x:.1f},{y:.1f}" for x, y in pts(R * lv / 4)) + '" fill="none" stroke="#c9d3d3" stroke-width=".5"/>'
    for (x, y) in pts(R):
        g += f'<line x1="{cx}" y1="{cy}" x2="{x:.1f}" y2="{y:.1f}" stroke="#c9d3d3" stroke-width=".5"/>'
    for k, (x, y) in enumerate(pts(R + 7)):
        anc = "middle" if abs(x - cx) < 3 else ("start" if x > cx else "end")
        g += f'<text x="{x:.1f}" y="{y + 1.5:.1f}" font-size="5" text-anchor="{anc}" font-family="Poppins" fill="#1F2A44">{labs[k]}</text>'
    return f'<svg viewBox="-10 0 140 100" width="{w}mm" style="max-width:100%">{g}</svg>'


